}
async function fileBase64(file){if(file.size>8*1024*1024){throw new Error('Confirmation files must be smaller than 8 MB.');}return new Promise((resolve,reject)=>{const r=new globalThis.FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('Could not read the attachment.'));r.readAsDataURL(file);});}
async function confirmDialog(){
 readForm();if(await ctx.state.workspace.get(`editquote:${edit.id}`)){throw new Error('Save your draft edits as a revision before confirmation.');}
 if(!navigator.onLine){throw new Error('Connect to the internet to confirm and create Sales Orders.');}
 await ctx.sync();if((await ctx.state.workspace.pending()).length){throw new Error('Sync or review pending work before confirmation.');}
 quote=await ctx.api(`/quotes/${quote.id}`);const commandId=newId(),fileIds=new Map(),confirmedAt=new Date().toISOString();
 const el=modal('Confirm & Create Sales Orders',`<p><strong>${escape(quoteNumber(quote))} · r${quote.revision}</strong></p><p>${escape(quote.snapshot.customerName)} · ${money(quote.snapshot.totalMinor)} CAD</p><p>The accepted revision will be locked. A Sales Order for each company will be created or linked in NetSuite: ${escape(Object.keys(quote.snapshot.companies).join(', '))}.</p><form id="quote-confirm-form" class="stack"><label>Customer who confirmed<input name="confirmedBy" value="${escape(quote.snapshot.contact)}" required></label><label>Confirmation time<input name="confirmedAt" value="${confirmedAt}" required></label><label>Confirmation note<textarea name="note"></textarea></label><label>Confirmation evidence (optional)<input id="confirmation-files" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" multiple></label></form>`,'<button data-close>Cancel</button><button form="quote-confirm-form" id="submit-confirmation" class="primary">Confirm & Create Sales Orders</button>');
 on('#quote-confirm-form','submit',async(e,f)=>{e.preventDefault();const button=$('#submit-confirmation',el);button.disabled=true;try{const files=[...$('#confirmation-files',el).files];if(files.length>10){throw new Error('Attach up to 10 files.');}const evidenceIds=[];for(const file of files){let id=fileIds.get(file);if(!id){id=newId();fileIds.set(file,id);}await ctx.api(`/quotes/${quote.id}/evidence`,{id,revision:quote.revision,name:file.name,base64:await fileBase64(file)});evidenceIds.push(id);}await ctx.api('/commands',{id:commandId,kind:'quote.confirm',payload:{id:quote.id,revision:quote.revision,...values(f),evidenceIds}});el.close();await openQuote(quote.id);}finally{button.disabled=false;}},el);
}
async function legacyQuote(){
 const s=quote.snapshot;view.innerHTML=pageHead(quoteNumber(quote),'Historical mixed-company quote','<button id="back-quotes">← All quotes</button>')+`<section class="panel panel-pad stack"><p>${escape(s.customerName)} · ${escape(s.jobsite?.address)}</p><strong>${money(s.totalMinor)}</strong><p>Keep this history and copy all items into one new quote for review.</p><button id="split-legacy">Create combined draft</button><button id="legacy-pdf">Download historical PDF</button></section>`;
